/* Dodatkowe, sprawdzone lokalne karty do szkolnych i codziennych pytań. */

function card(subject, title, keywords, short, explanation, example, related, check) {
  return { subject, title, keywords: keywords.split("|").map(value => value.trim()), aliases: [], short, explanation, example, related, check };
}

